<?php
require __DIR__.'/_ui.php'; cms_require('media'); $id=(int)($_GET['id']??0); $media=cms_row('SELECT * FROM media WHERE id=?',[$id]);
if (!$media) { http_response_code(404); exit('Datei nicht gefunden.'); }
ui_start('Mediendetails',$media['original_name'],ui_link('← Zur Mediathek','/admin/media.php'));
?><div class="workspace-columns"><section class="workspace-card"><?php if (str_starts_with($media['mime'],'image/')): ?><img style="max-width:100%;max-height:360px" src="<?= e(media_url($media)) ?>" alt="<?= e($media['alt_text']??'') ?>"><?php endif; ?><p><?= e($media['mime'].' · '.format_bytes((int)$media['size'])) ?></p><?= ui_link('Datei öffnen',str_replace(site_url(),'',media_url($media))) ?></section><section class="workspace-card"><?php ui_form_start('media.save','/admin/media_details.php?id='.$id,['id'=>$id]); ui_field('folder','Sammlung / Ordner',$media['folder']); ui_field('alt_text','Alternativtext',$media['alt_text']??'','textarea','Beschreiben Sie den Bildinhalt.'); ui_field('caption','Bildunterschrift',$media['caption']??''); ui_field('copyright','Urheber / Nutzungsrechte',$media['copyright']??''); ui_submit(); ?></section></div><section class="workspace-card"><h2>Verwendung in Seiten</h2><?php $found=false; foreach (fetch_pages() as $p) { if (!cms_can_page((int)$p['id'])) continue; if (str_contains($p['blocks_json']??'',$media['filename'])) { echo '<p>'.ui_link($p['title'],'/admin/editor.php?id='.$p['id']).'</p>'; $found=true; } } if (!$found) ui_empty('Keine direkte Verwendung gefunden','Geprüft wurden die Arbeitsstände Ihrer Seiten. Externe Verwendungen werden nicht erfasst.'); ?></section><?php ui_end();
